{
  "decision-shared-asset-exit-buyout": "SELECT e.asset_code, (MAX(b.floor_cents, e.cost_cents - (e.exit_month - e.service_month) * b.rate_cents) * e.stake_bp) / 10000 AS payout_cents, b.source_id FROM equipment_exit AS e JOIN rate_bulletin AS b ON b.source_id = (SELECT r.source_id FROM rate_bulletin AS r WHERE r.asset_class = e.asset_class AND r.start_month <= e.exit_month ORDER BY r.start_month DESC, r.revision_no DESC LIMIT 1) ORDER BY e.asset_code COLLATE BINARY",
  "decision-shared-circuit-kiln-dispatch": "SELECT g.kiln_id AS glaze_kiln, b.kiln_id AS bisque_kiln, MAX(g.run_min, b.run_min) AS finish_min, g.price_cents + b.price_cents AS total_cents, n.source_id FROM firing_options AS g JOIN firing_options AS b ON g.kiln_id <> b.kiln_id CROSS JOIN circuit_notice AS n WHERE g.load_kind = 'glaze' AND b.load_kind = 'bisque' AND g.draw_kw + b.draw_kw <= n.limit_kw ORDER BY finish_min, total_cents, glaze_kiln COLLATE BINARY, bisque_kiln COLLATE BINARY LIMIT 1",
  "decision-shared-crate-loan-pair": "WITH pairs AS (SELECT a.loan_code AS first_loan, b.loan_code AS second_loan, a.handling_cents + b.handling_cents + ca.fee_cents + CASE WHEN a.crate_code = b.crate_code THEN 0 ELSE cb.fee_cents END AS booking_cents, a.interpretation_points + b.interpretation_points AS total_points FROM loan_offer AS a JOIN loan_offer AS b ON a.loan_code COLLATE BINARY < b.loan_code JOIN crate_tariff AS ca ON ca.crate_code = a.crate_code JOIN crate_tariff AS cb ON cb.crate_code = b.crate_code) SELECT first_loan, second_loan, booking_cents, total_points FROM pairs WHERE booking_cents <= 760 ORDER BY total_points DESC, booking_cents, first_loan COLLATE BINARY, second_loan COLLATE BINARY LIMIT 1",
  "decision-shared-yard-highest-value-use": "WITH pairs AS (SELECT a.use_code AS pad_a_use, b.use_code AS pad_b_use, a.conversion_cents + b.conversion_cents + CASE WHEN a.load_units > 0 OR b.load_units > 0 THEN t.activation_cents ELSE 0 END AS outlay_cents, a.gross_pv + b.gross_pv AS gross_cents, t.outlay_cap FROM pad_option AS a CROSS JOIN pad_option AS b CROSS JOIN yard_terms AS t WHERE a.pad_code = 'A' AND b.pad_code = 'B' AND a.load_units + b.load_units <= t.load_cap) SELECT pad_a_use, pad_b_use, outlay_cents, gross_cents - outlay_cents AS yard_value_cents FROM pairs WHERE outlay_cents <= outlay_cap ORDER BY yard_value_cents DESC, outlay_cents, pad_a_use COLLATE BINARY, pad_b_use COLLATE BINARY LIMIT 1"
}
